import logging
import uuid

logger = logging.getLogger(__name__)

class OrderService:
    def __init__(self, stock) -> None:
        self.stock = stock

    def place_order(self, user: str, item: str, quantity: int, is_admin: bool = False) -> tuple[int, str]:
        try:
            reservation_id = self.stock.reserve(item, quantity)
        except Exception as exc:
            # Unexpected error from the inventory service
            ref = uuid.uuid4().hex[:12]
            logger.exception(
                "Order failed [ref=%s] user=%r item=%r quantity=%r",
                ref, user, item, quantity,
            )
            if is_admin:
                detail = f"{type(exc).__name__}: {exc}"
                message = (
                    f"An unexpected error occurred (ref: {ref}). "
                    f"Technical details: {detail}"
                )
            else:
                message = (
                    f"An unexpected error occurred (ref: {ref}). "
                    f"Please contact support with this reference code."
                )
            return 500, message

        return 200, f"Your order of {quantity} x {item!r} was placed successfully (reservation {reservation_id})."
